{"content":[{"type":"text","text":"import type {
  AuthenticatedConsoleContext,
  ConsoleSessionPort,
  ConsoleSessionResult,
} from "../session/ConsoleSession";
import type { ConsoleLocale } from "../i18n/i18n";

function isAuthenticatedConsoleContext(value: unknown): value is AuthenticatedConsoleContext {
  if (typeof value !== "object" || value === null) return false;
  const candidate = value as Record<string, unknown>;
  const session = candidate.session as Record<string, unknown> | undefined;
  const scope = session?.scope as Record<string, unknown> | undefined;
  return typeof candidate.attentionCount === "number"
    && (candidate.locale === undefined || typeof candidate.locale === "string")
    && session?.kind === "authenticated"
    && typeof session.principalName === "string"
    && typeof scope?.id === "string"
    && typeof scope?.name === "string";
}

export const browserSessionAdapter: ConsoleSessionPort = {
  async readConsoleSession(): Promise<ConsoleSessionResult> {
    try {
      const response = await fetch("/api/console/session", { credentials: "same-origin" });
      if (response.status === 401) return { kind: "anonymous" };
      if (!response.ok) return { kind: "unavailable" };

      const context: unknown = await response.json();
      return isAuthenticatedConsoleContext(context)
        ? { kind: "authenticated", context }
        : { kind: "unavailable" };
    } catch {
      return { kind: "unavailable" };
    }
  },
  async saveConsoleLocale(locale: ConsoleLocale): Promise<boolean> {
    try {
      const response = await fetch("/api/console/session/locale", {
        body: JSON.stringify({ locale }),
        credentials: "same-origin",
        headers: { "content-type": "application/json" },
        method: "PUT",
      });
      return response.ok;
    } catch {
      return false;
    }
  },
};
