{"content":[{"type":"text","text":"import React, { useCallback, useEffect, useState } from "react";
import { BrowserRouter, Route, Routes } from "react-router";
import { I18nextProvider, useTranslation } from "react-i18next";

import {
  changeConsoleLanguage,
  consoleI18n,
  persistAnonymousConsoleLocale,
  resolveConsoleLocale,
  type ConsoleLocale,
} from "../i18n/i18n";
import { browserSessionAdapter } from "../platform/BrowserSessionAdapter";
import type { ConsoleSessionPort, ConsoleSessionResult } from "../session/ConsoleSession";
import {
  ConsoleErrorBoundary,
  ConsoleSessionStatus,
  ConsoleShell,
  LoginHandoff,
  LoginRoute,
} from "../shell/ConsoleShell";

type ConsoleViewState = ConsoleSessionResult | { kind: "resolving" };

function ConsoleWorkSurface() {
  const { t } = useTranslation("common");
  return <section><h1>{t("console")}</h1><p>{t("workSurfaceDescription")}</p></section>;
}

type ConsoleRoutesProps = {
  locale: ConsoleLocale;
  onLanguageChange: (locale: ConsoleLocale) => void;
  onRetry: () => void;
  state: ConsoleViewState;
};

function ConsoleRoutes({ locale, onLanguageChange, onRetry, state }: ConsoleRoutesProps) {
  if (state.kind === "resolving") return <ConsoleSessionStatus kind="resolving" />;
  if (state.kind === "unavailable") return <ConsoleSessionStatus kind="unavailable" onRetry={onRetry} />;

  if (state.kind === "anonymous") {
    return (
      <Routes>
        <Route path="/login" element={<LoginRoute locale={locale} onLanguageChange={onLanguageChange} />} />
        <Route path="*" element={<LoginHandoff locale={locale} onLanguageChange={onLanguageChange} />} />
      </Routes>
    );
  }

  return (
    <ConsoleShell
      attentionCount={state.context.attentionCount}
      context={state.context.session}
      locale={locale}
      onLanguageChange={onLanguageChange}
    >
      <Routes><Route path="*" element={<ConsoleWorkSurface />} /></Routes>
    </ConsoleShell>
  );
}

export function ConsoleApplication({ sessionAdapter = browserSessionAdapter }: { sessionAdapter?: ConsoleSessionPort }) {
  const [state, setState] = useState<ConsoleViewState>({ kind: "resolving" });
  const [locale, setLocale] = useState<ConsoleLocale>(() => resolveConsoleLocale());

  const loadSession = useCallback(() => {
    setState({ kind: "resolving" });
    void sessionAdapter.readConsoleSession().then((nextState) => {
      setState(nextState);
      setLocale(resolveConsoleLocale(nextState.kind === "authenticated" ? nextState.context.locale : undefined));
    });
  }, [sessionAdapter]);

  useEffect(() => {
    void changeConsoleLanguage(locale);
    if (typeof document !== "undefined") document.documentElement.lang = locale;
  }, [locale]);

  useEffect(() => {
    loadSession();
  }, [loadSession]);

  const changeLanguage = (nextLocale: ConsoleLocale) => {
    if (state.kind === "anonymous") {
      persistAnonymousConsoleLocale(nextLocale);
      setLocale(nextLocale);
      return;
    }
    if (state.kind === "authenticated") {
      void sessionAdapter.saveConsoleLocale(nextLocale).then((saved) => {
        if (saved) setLocale(nextLocale);
      });
    }
  };

  return (
    <I18nextProvider i18n={consoleI18n}>
      <BrowserRouter>
        <ConsoleErrorBoundary>
          <ConsoleRoutes locale={locale} onLanguageChange={changeLanguage} onRetry={loadSession} state={state} />
        </ConsoleErrorBoundary>
      </BrowserRouter>
    </I18nextProvider>
  );
}
"}]}

